const btns = document.querySelectorAll('.ai4a11y-plain-btn');
const adapter = globalThis.__ai4a11yRuntime?.adapters?.preview?.adapter;
if (!adapter || !adapter.s || adapter.s.ended) {
  return btns.length === 0;
}
// Exactly 2 sections have long paragraphs (about and eligibility)
if (btns.length !== 2) return false;
for (const btn of btns) {
  if (!btn.classList.contains('ai4a11y-plain-section-btn')) return false;
  if (btn.textContent.trim() !== 'Plain language') return false;
}
return true;

const adapter = globalThis.__ai4a11yRuntime?.adapters?.preview?.adapter;
if (!adapter || !adapter.s || adapter.s.ended) return true;
const section2Btn = document.querySelectorAll('.ai4a11y-plain-section-btn')[1];
if (!section2Btn) return false;

const p2 = document.getElementById('para-long-2');
const p3 = document.getElementById('para-long-3');

// Click to simplify section
section2Btn.click();
await new Promise(r => setTimeout(r, 60));

const bothHidden = p2.hasAttribute('hidden') && p3.hasAttribute('hidden');
const btnShowsOriginal = section2Btn.textContent.trim() === 'Show original';

// Click to restore original
section2Btn.click();
await new Promise(r => setTimeout(r, 60));

const bothVisible = !p2.hasAttribute('hidden') && !p3.hasAttribute('hidden');
const btnShowsPlain = section2Btn.textContent.trim() === 'Plain language';

return bothHidden && btnShowsOriginal && bothVisible && btnShowsPlain;

const adapter = globalThis.__ai4a11yRuntime?.adapters?.preview?.adapter;
if (!adapter || !adapter.s || adapter.s.ended) return true;

const testSec = document.createElement('section');
testSec.id = 'test-wrapped-section';
const wrap = document.createElement('div');
wrap.className = 'content-wrapper';
const p = document.createElement('p');
p.textContent = 'A comprehensive medical guide explaining patient rights, clinical protocols, prescription monitoring requirements, and emergency healthcare procedures across municipal districts.'.repeat(2);
wrap.appendChild(p);
testSec.appendChild(wrap);
document.querySelector('main').appendChild(testSec);

adapter.disable();
adapter.enable({ maxParagraphsBeforeSection: 2 });

const btn = testSec.querySelector('.ai4a11y-plain-btn');
const placedBefore = btn && btn.nextElementSibling === wrap;

adapter.disable();
testSec.remove();
adapter.enable({ maxParagraphsBeforeSection: 2 });

return Boolean(placedBefore);

