const adapter = globalThis.__ai4a11yRuntime?.adapters?.preview?.adapter;
if (!adapter || !adapter.s || adapter.s.ended) return true;

const testP = document.createElement('p');
const longLink = document.createElement('a');
longLink.href = '#';
longLink.textContent = 'This is an exceptionally long anchor text that exceeds eighty characters in total length to verify bounds';
testP.appendChild(longLink);
for (let i = 0; i < 60; i++) {
  const numSpan = document.createElement('span');
  numSpan.textContent = ' number ' + (1000 + i);
  testP.appendChild(numSpan);
}
testP.appendChild(document.createTextNode(' A comprehensive guide explaining protocols across municipal districts.'.repeat(2)));
document.querySelector('main').appendChild(testP);

adapter.disable();
adapter.enable({ maxParagraphsBeforeSection: 20 });

const btn = testP.nextElementSibling;
let captured = null;
const origAi = globalThis.__verifyAi;
globalThis.__verifyAi = async (req) => {
  captured = req;
  return origAi ? origAi(req) : 'Simplified.';
};

btn.click();
await new Promise(r => setTimeout(r, 60));
globalThis.__verifyAi = origAi;

const terms = captured?.options?.keep || [];
const allUnder80 = terms.length > 0 && terms.every(t => typeof t === 'string' && t.length <= 80);
const atMost50 = terms.length <= 50;

adapter.disable();
testP.remove();
adapter.enable({ maxParagraphsBeforeSection: 2 });

return allUnder80 && atMost50;
